  ('pt-BR', 'mods.create.hint', $json$"Abre a página Mods do site, onde você cria o mod neste ambiente."$json$::jsonb),
  ('en', 'mods.create.hint', $json$"Opens the Mods page of the site, where you create the mod in this environment."$json$::jsonb),
  ('es', 'mods.create.hint', $json$"Abre la página Mods del sitio, donde creas el mod en este entorno."$json$::jsonb),
  ('zh-CN', 'mods.create.hint', $json$"打开网站的“模组”页面，在此环境中创建模组。"$json$::jsonb),
  ('hi', 'mods.create.hint', $json$"साइट का मॉड पेज खोलता है, जहाँ आप इस परिवेश में मॉड बनाते हैं।"$json$::jsonb),
  ('ar', 'mods.create.hint', $json$"يفتح صفحة الإضافات على الموقع، حيث تنشئ الإضافة في هذه البيئة."$json$::jsonb),
  ('fr', 'mods.create.hint', $json$"Ouvre la page Mods du site, où vous créez le mod dans cet environnement."$json$::jsonb),
  ('ru', 'mods.create.hint', $json$"Открывает страницу «Моды» на сайте, где вы создаёте мод в этой среде."$json$::jsonb),
  ('ja', 'mods.create.hint', $json$"サイトの Mod ページを開き、この環境で Mod を作成します。"$json$::jsonb),
  ('de', 'mods.create.hint', $json$"Öffnet die Seite Mods der Website, auf der Sie den Mod in dieser Umgebung erstellen."$json$::jsonb),
  ('pt-BR', 'mods.empty.site', $json$"Nenhum mod seu ainda. Criar mod abre o site, onde você liga outro LLM: um programa de linha de comando ou uma API."$json$::jsonb),
  ('en', 'mods.empty.site', $json$"No mod of your own yet. Create mod opens the site, where you connect another LLM: a command-line program or an API."$json$::jsonb),
  ('es', 'mods.empty.site', $json$"Todavía no tienes mods propios. Crear mod abre el sitio, donde conectas otro LLM: un programa de línea de comandos o una API."$json$::jsonb),
  ('zh-CN', 'mods.empty.site', $json$"还没有自己的模组。“创建模组”会打开网站，在那里接入另一个 LLM：命令行程序或 API。"$json$::jsonb),
  ('hi', 'mods.empty.site', $json$"अभी आपका कोई मॉड नहीं है। मॉड बनाएँ साइट खोलता है, जहाँ आप कोई दूसरा LLM जोड़ते हैं: कमांड-लाइन प्रोग्राम या API।"$json$::jsonb),
  ('ar', 'mods.empty.site', $json$"لا توجد إضافات خاصة بك بعد. «إنشاء إضافة» يفتح الموقع، حيث تربط نموذج LLM آخر: برنامج سطر أوامر أو واجهة API."$json$::jsonb),
  ('fr', 'mods.empty.site', $json$"Aucun mod à vous pour l’instant. Créer un mod ouvre le site, où vous connectez un autre LLM : un programme en ligne de commande ou une API."$json$::jsonb),
  ('ru', 'mods.empty.site', $json$"Своих модов пока нет. «Создать мод» открывает сайт, где вы подключаете другую LLM: программу командной строки или API."$json$::jsonb),
  ('ja', 'mods.empty.site', $json$"自分の Mod はまだありません。「Mod を作成」でサイトが開き、別の LLM（コマンドラインプログラムまたは API）をつなげます。"$json$::jsonb),
  ('de', 'mods.empty.site', $json$"Noch kein eigener Mod. Mod erstellen öffnet die Website, auf der Sie ein weiteres LLM anbinden: ein Kommandozeilenprogramm oder eine API."$json$::jsonb),
  ('pt-BR', 'mods.templates', $json$"Do catálogo"$json$::jsonb),
