  ('pt-BR', 'site.mods.yours.description', $json$"Os mods que você criou neste ambiente. A chave de API e os modelos se configuram no app, na aba do mod."$json$::jsonb),
  ('en', 'site.mods.yours.description', $json$"The mods you created in this environment. The API key and the models are set in the app, in the mod's tab."$json$::jsonb),
  ('es', 'site.mods.yours.description', $json$"Los mods que creaste en este entorno. La clave de API y los modelos se configuran en la app, en la pestaña del mod."$json$::jsonb),
  ('zh-CN', 'site.mods.yours.description', $json$"你在此环境中创建的模组。API 密钥和模型在应用中模组的标签页里设置。"$json$::jsonb),
  ('hi', 'site.mods.yours.description', $json$"इस परिवेश में आपके बनाए मॉड। API कुंजी और मॉडल ऐप में, मॉड के टैब में सेट होते हैं।"$json$::jsonb),
